        s["EXCISION_OF_VALVE_AND_ANNULAR_DEBRIDEMENTTXT"].alias("excision_of_valve_and_annular_debridementtxt"),
        s["REPAIR_OF_VALVETXT"].alias("repair_of_valvetxt"),
